function injectCSS(id, css){
  let el = document.getElementById(id);
  if(!el){el=document.createElement('style');el.id=id;document.head.appendChild(el);}
  el.textContent=css;
}

/* ═══════════════════════════════════════════════════════════════════════════
   MAIN COMPONENT
═══════════════════════════════════════════════════════════════════════════ */
export default function Login({ onLoginSuccess }) {
  const [step, setStep]             = useState(1);        // 1=login form, 2=OTP
  const [ucc, setUcc]               = useState('');
  const [dob, setDob]               = useState('');
  const [termsAccepted, setTerms]   = useState(false);
  const [showTerms, setShowTerms]   = useState(false);
  const [modalChecked, setMChk]     = useState(false);
  const [otp, setOtp]               = useState(['','','','','','']);  // 6 boxes
  const [otpSecs, setOtpSecs]       = useState(300);
  const [resendCD, setResendCD]     = useState(60);
  const [loading, setLoading]       = useState(false);
  const [error, setError]           = useState('');
  const [sessionId, setSessionId]   = useState('');
  const otpRef0 = useRef(null);
  const otpRef1 = useRef(null);
  const otpRef2 = useRef(null);
  const otpRef3 = useRef(null);
  const otpRef4 = useRef(null);
  const otpRef5 = useRef(null);
  const otpRefs = [otpRef0, otpRef1, otpRef2, otpRef3, otpRef4, otpRef5];
  const timerRef = useRef(null);

  useEffect(() => { injectCSS('nb-login-css', _css); }, []);

  /* ── OTP timer ── */
  useEffect(() => {
    if (step !== 2) return;
    setOtpSecs(300); setResendCD(60);
    timerRef.current = setInterval(() => {
      setOtpSecs(s => { if(s<=1){clearInterval(timerRef.current);return 0;} return s-1; });
      setResendCD(r => r>0 ? r-1 : 0);
    }, 1000);
    return () => clearInterval(timerRef.current);
  }, [step]);

  const fmtTime = s => `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
  const canSend  = ucc.trim().length>=5 && ucc.trim().length<=8 && dob && termsAccepted;
  const otpFull  = otp.every(d => d !== '');

  /* ── Send OTP ── */
  const handleSendOTP = async () => {
    setLoading(true); setError('');
    try {
      const res  = await initiateLogin(ucc.trim().toUpperCase(), dob);
      const data = res.data;
      if (!data.sessionId) throw new Error(data.error || 'Failed to send OTP');
      setSessionId(data.sessionId);
      setStep(2);
    } catch (err) {
      const msg = err.response?.data?.error || err.response?.data?.message || err.message || 'Failed to send OTP. Please try again.';
      setError(msg);
    }
    setLoading(false);
  };

  /* ── Verify OTP ── */
  const handleVerify = async () => {
    setLoading(true); setError('');
    try {
      const res  = await verifyOTPApi(sessionId, otp.join(''));
      const data = res.data;
      if (!data.token) throw new Error(data.error || 'Invalid OTP');
      localStorage.setItem('nb_token', data.token);
      localStorage.setItem('nb_client', JSON.stringify({
        name:   data.clientName,
        ucc:    data.ucc,
        mobile: data.mobile || '',
        email:  data.email  || '',
        dob:    data.dob    || ''
      }));
      clearInterval(timerRef.current);
      onLoginSuccess({
        clientName: data.clientName,
        ucc:        data.ucc,
        mobile:     data.mobile || '',
        email:      data.email  || '',
        dob:        data.dob    || ''
      });
    } catch (err) {
      setError(err.message || 'Invalid OTP. Please try again.');
    }
    setLoading(false);
  };

  /* ── OTP input handling ── */
  const handleOtpInput = (val, idx) => {
    const v = val.replace(/[^0-9]/g,'');
    const next = [...otp]; next[idx] = v;
    setOtp(next);
    if (v && idx < 5) otpRefs[idx+1].current?.focus();
  };
  const handleOtpKeyDown = (e, idx) => {
    if (e.key==='Backspace' && !otp[idx] && idx>0) {
      otpRefs[idx-1].current?.focus();
      const next=[...otp]; next[idx-1]=''; setOtp(next);
    }
  };

  /* ── Accept terms → auto-proceed if form complete ── */
  const acceptTerms = () => {
    setTerms(true);
    setShowTerms(false);
    setMChk(false);
    if (ucc.trim().length>=5 && ucc.trim().length<=8 && dob) {
      setTimeout(handleSendOTP, 100); // slight delay to let state settle
    }
  };

  /* ─────────────────────────────────────────────────────────────────────────
     LEFT PANEL (shared by login + OTP)
  ───────────────────────────────────────────────────────────────────────── */
  const LeftPanel = ({ isOTP }) => (
    <div className="nb-left">
      <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:28,flexShrink:0}}>
        <img src={LOGO_URI} style={{height:36,width:'auto',objectFit:'contain'}} alt="Navia Markets"/>
        <div>
          <div style={{fontSize:15,fontWeight:600,color:'#0D0F12'}}>Navia Backup</div>
          <div style={{fontSize:11,color:'#9BA3B0'}}>by Navia Markets Ltd</div>
        </div>
      </div>
      <div className="nb-status-pill">
        <span className="nb-sdot"/>
        {isOTP ? 'Identity verification' : 'Emergency access system'}
      </div>
      {isOTP ? (
        <>
          <h1 className="nb-hero-title">One last step<br/>to <span>secure access</span></h1>
          <p className="nb-hero-desc">We've sent a 6-digit OTP to your registered mobile number and email address. Enter it within 5 minutes to access your account.</p>
          <div className="nb-feat-list">
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#EEF2FF'}}>⏱</div><span>OTP valid for 5 minutes only</span></div>
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#E8F5E9'}}>🔒</div><span>Never share your OTP — Navia will never ask for it</span></div>
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#FFF8E1'}}>📱</div><span>Check registered mobile and email inbox</span></div>
          </div>
          <div className="nb-help-card">
            <div className="nb-help-title">Didn't receive OTP?</div>
            <div style={{fontSize:13,color:'#5A6272',lineHeight:1.7}}>Check spam folder &nbsp;·&nbsp; Ensure mobile network is active &nbsp;·&nbsp; Wait 30 seconds before requesting again</div>
          </div>
        </>
      ) : (
        <>
          <h1 className="nb-hero-title">Protect your trades<br/>during <span>platform downtime</span></h1>
          <p className="nb-hero-desc">When the primary trading platform is unavailable, Navia Backup lets you square off open positions at market price — keeping you in control during critical moments.</p>
          <div className="nb-feat-list">
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#FFF8E1'}}>⚡</div><span>Square off existing positions instantly at market price</span></div>
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#E8F5E9'}}>✓</div><span>NSE, BSE &amp; MCX segments supported</span></div>
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#FFF3E0'}}>🔒</div><span>OTP verified secure access every session</span></div>
            <div className="nb-feat"><div className="nb-feat-ic" style={{background:'#EEF2FF'}}>📊</div><span>View net, day &amp; B/F positions with real-time data</span></div>
          </div>
          <div className="nb-help-card">
            <div className="nb-help-title">Need help?</div>
            <a href="mailto:support@navia.co.in" className="nb-help-link">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>
              support@navia.co.in
            </a>
            <a href="https://support.navia.co.in" target="_blank" rel="noreferrer" className="nb-help-link">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z"/></svg>
              support.navia.co.in
            </a>
          </div>
        </>
      )}
      <div className="nb-left-footer">
        Navia Markets Ltd &nbsp;·&nbsp; naviabackup.co.in<br/>
        Trades via this portal will not reflect immediately in the main app.
      </div>
    </div>
  );

  /* ─────────────────────────────────────────────────────────────────────────
     TERMS MODAL
  ───────────────────────────────────────────────────────────────────────── */
  const TermsModal = () => (
    <div className="nb-modal-overlay" onClick={e => e.target===e.currentTarget && setShowTerms(false)}>
      <div className="nb-tbox">
        <div className="nb-tbhdr">
          <div style={{fontSize:15,fontWeight:600,color:'#0D0F12'}}>Terms &amp; Conditions</div>
          <button onClick={() => setShowTerms(false)} style={{background:'none',border:'none',cursor:'pointer',color:'#5A6272',fontSize:18}}>✕</button>
        </div>
        <div className="nb-tbbody">
          {/* Warning header */}
          <div style={{display:'flex',alignItems:'flex-start',gap:12,marginBottom:20,padding:14,background:'#FFFBEB',border:'0.5px solid #D97706',borderRadius:8}}>
            <div style={{width:36,height:36,background:'#FFF3CD',borderRadius:8,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#D97706" strokeWidth="2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
            </div>
            <div>
              <div style={{fontSize:14,fontWeight:600,color:'#0D0F12',marginBottom:2}}>Navia Backup — Important Instructions</div>
              <div style={{fontSize:12,color:'#5A6272'}}>Please read carefully before proceeding</div>
            </div>
          </div>
          {/* 10 instructions */}
          <ol style={{listStyle:'none',display:'flex',flexDirection:'column',gap:12}}>
            {[
              'Square-off option is enabled only during downtime.',
              'Only market square-off for full qty is allowed.',
              'Orders go to Exchange on a best-effort, 5-min cycle.',
              'T+1 shares (bought yesterday) cannot be sold today.',
              'Once placed, square-off will be executed.',
              'Trade confirmation sent via WhatsApp.',
              'As a stand-alone system, trades may not reflect immediately in the App.',
              'Do not repeat trades when the App resumes.',
              'Navia is not liable for losses using Backup.',
            ].map((text, i) => (
              <li key={i} style={{display:'flex',alignItems:'flex-start',gap:12}}>
                <span style={{minWidth:24,height:24,background:'#EEF2FF',color:'#0C447C',borderRadius:'50%',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:600,flexShrink:0,marginTop:1}}>{i+1}</span>
                <span style={{fontSize:13,color:'#5A6272',lineHeight:1.6}}>{text}</span>
              </li>
            ))}
            <li style={{display:'flex',alignItems:'flex-start',gap:12}}>
              <span style={{minWidth:24,height:24,background:'#EEF2FF',color:'#0C447C',borderRadius:'50%',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:600,flexShrink:0,marginTop:1}}>10</span>
              <span style={{fontSize:13,color:'#5A6272',lineHeight:1.6}}>More details on <a href="https://support.navia.co.in" target="_blank" rel="noreferrer" style={{color:'#1B4FD8'}}>Navia Support</a>.</span>
            </li>
          </ol>
        </div>
        <div className="nb-tbftr">
          <div style={{display:'flex',alignItems:'flex-start',gap:10}}>
            <input type="checkbox" id="tc-modal-chk" checked={modalChecked}
              onChange={e => setMChk(e.target.checked)}
              style={{width:16,height:16,accentColor:'#1B4FD8',flexShrink:0,marginTop:2,cursor:'pointer'}}/>
            <label htmlFor="tc-modal-chk" style={{fontSize:13,color:'#5A6272',lineHeight:1.55,cursor:'pointer'}}>
              I have read and understood all the above instructions
            </label>
          </div>
          <div style={{display:'flex',gap:10}}>
            <button className="nb-tc-cancel-btn" onClick={() => setShowTerms(false)}>Cancel</button>
            <button className="nb-tc-accept-btn" disabled={!modalChecked} onClick={acceptTerms}>
              Accept &amp; Continue
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  /* ─────────────────────────────────────────────────────────────────────────
     RENDER
  ───────────────────────────────────────────────────────────────────────── */
  return (
    <div className="nb-login-root">
      {showTerms && <TermsModal />}

      {/* ── Mobile-only branded header (replaces left panel on small screens) ── */}
      <div className="nb-mobile-hdr">
        <div className="nb-mobile-hdr-logo-wrap">
          <img src={LOGO_URI} className="nb-mobile-hdr-logo" alt="Navia Markets"/>
        </div>
        <div className="nb-mobile-hdr-name">Navia Backup</div>
        <div className="nb-mobile-hdr-sub">
          Emergency square-off portal{step===2 ? ' · Identity verification' : ''}
        </div>
        <div className="nb-mobile-pill">
          <span className="nb-mobile-pill-dot"/>
          {step===2 ? 'Verify OTP' : 'Emergency access system'}
        </div>
      </div>

      <LeftPanel isOTP={step===2} />

      <div className="nb-right">
        {/* ── STEP 1: Login form ── */}
        {step===1 && (
          <div className="nb-form-box">
            <div className="nb-step-dots">
              <div className="nb-dot nb-dot-active" />
              <div className="nb-dot nb-dot-idle" />
            </div>
            <h2 className="nb-form-title">Sign in to your account</h2>
            <p className="nb-form-sub">Enter your UCC and date of birth to continue</p>
            <div className="nb-fgrp">
              <div className="nb-flbl">
                UCC (Unique Client Code)
                <span className="nb-fhint">5–8 alphanumeric (e.g. AB1234)</span>
              </div>
              <input className="nb-finp" type="text" placeholder="Enter your UCC"
                value={ucc} onChange={e => setUcc(e.target.value.toUpperCase())}
                maxLength={8} autoComplete="username" inputMode="text"/>
            </div>
            <div className="nb-fgrp">
              <div className="nb-flbl">Date of birth</div>
              <input className="nb-finp" type="date" value={dob}
                onChange={e => setDob(e.target.value)} autoComplete="bday"/>
            </div>
            {/* Terms row — clicking always opens popup */}
            <div className="nb-terms-row" onClick={() => setShowTerms(true)}>
              <input type="checkbox" checked={termsAccepted} readOnly
                onClick={e => {e.stopPropagation(); setShowTerms(true);}}
                style={{width:15,height:15,accentColor:'#1B4FD8',cursor:'pointer',flexShrink:0,marginTop:2}}/>
              <div className="nb-terms-txt">
                I agree to the{' '}
                <a href="#terms" onClick={e => {e.preventDefault();e.stopPropagation();setShowTerms(true);}}>
                  Terms &amp; Conditions
                </a>
                {' '}and important instructions. I understand square-off orders execute at market price and cannot be cancelled.
              </div>
            </div>
            {error && <div style={{fontSize:12,color:'#DC2626',marginBottom:12}}>{error}</div>}
            <button className="nb-pri-btn" disabled={!canSend || loading} onClick={handleSendOTP}>
              {loading ? 'Sending OTP…' : 'Send OTP'}
              {!loading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>}
            </button>
            <div className="nb-sec-note">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>
              OTP verified &nbsp;·&nbsp; SEBI registered broker
            </div>
          </div>
        )}

        {/* ── STEP 2: OTP ── */}
        {step===2 && (
          <div className="nb-form-box">
            <div className="nb-step-dots">
              <div className="nb-dot nb-dot-done" />
              <div className="nb-dot nb-dot-active" />
            </div>
            <h2 className="nb-form-title">Verify your identity</h2>
            <p className="nb-form-sub">OTP sent to your registered mobile and email</p>
            <div className="nb-otp-info">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{flexShrink:0,marginTop:1}}><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              Enter the 6-digit OTP. Valid for 5 minutes only. Do not share with anyone.
            </div>
            <div style={{marginBottom:8}}>
              <div style={{fontSize:12,fontWeight:500,color:'#5A6272',marginBottom:9}}>6-digit OTP</div>
              <div className="nb-otp-grid">
                {otp.map((d, i) => (
                  <input key={i} ref={otpRefs[i]} className={'nb-otp-inp'+(d?' filled':'')}
                    type="text" maxLength={1} inputMode="numeric"
                    value={d} onChange={e => handleOtpInput(e.target.value, i)}
                    onKeyDown={e => handleOtpKeyDown(e, i)}
                    aria-label={`OTP digit ${i+1}`}/>
                ))}
              </div>
            </div>
            {/* Timer */}
            <div className="nb-timer-bar">
              <div className="nb-timer-top">
                <span className="nb-timer-lbl">OTP expires in</span>
                <span className={'nb-timer-val'+(otpSecs<=60?' urgent':'')}>{fmtTime(otpSecs)}</span>
              </div>
              <div className="nb-timer-track">
                <div className={'nb-timer-prog'+(otpSecs<=60?' urgent':'')}
                  style={{width:`${(otpSecs/300)*100}%`}}/>
              </div>
            </div>
            <div className="nb-resend-row">
              <button className={'nb-resend-btn'+(resendCD<=0?' active':'')}
                disabled={resendCD>0} onClick={() => {setOtp(['','','','','','']);setOtpSecs(300);setResendCD(60);}}>
                {resendCD>0 ? `Resend OTP (available in ${fmtTime(resendCD)})` : 'Resend OTP'}
              </button>
            </div>
            {error && <div style={{fontSize:12,color:'#DC2626',marginBottom:12}}>{error}</div>}
            <button className="nb-pri-btn" disabled={!otpFull || loading || otpSecs===0} onClick={handleVerify}>
              {loading ? 'Verifying…' : 'Verify and sign in'}
              {!loading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="20 6 9 17 4 12"/></svg>}
            </button>
            <button className="nb-back-btn" onClick={() => { clearInterval(timerRef.current); setStep(1); setOtp(['','','','','','']);setError(''); }}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>
              Back to edit details
            </button>
          </div>
        )}
      </div>
    </div>
  );
}